-- F2, the Finance Core's intake and open items (ADR-0090, docs/modules/finance-core.md §3.8): document
-- types and number series, the intake log, documents, open items, allocations, party balances and
-- reconcile runs in schema `fin`; Finance I's vouchers and receivables (payments, allocations,
-- ar_entries, customer_balances) dropped with no copy (ADR-0083 #2). Generated by drizzle-kit in two
-- steps (the new tables, then the drops), then by hand: the order of the keys an item's foreign key
-- needs, the REVOKEs and guards, the sub-ledger trigger, the data section, the drops in dependency
-- order and the assistant's views over the core.
CREATE TABLE "fin"."allocations" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "fin"."allocations_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
