	"amount" numeric(14, 2) NOT NULL,
	"document_id" bigint NOT NULL,
	"reverses_allocation_id" bigint,
	"mirror" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "fin_allocations_company_id_key" UNIQUE("company_id","id"),
	CONSTRAINT "fin_allocations_company_reverses_key" UNIQUE("company_id","reverses_allocation_id"),
	CONSTRAINT "fin_allocations_amount" CHECK ("fin"."allocations"."amount" > 0),
