-- ---------------------------------------------------------------------------------------------
-- Hand-written below (ADR-0090; docs/modules/finance-core.md §3.8, §4, §6): F2's intake.
-- ---------------------------------------------------------------------------------------------

-- Nothing in `fin` is deleted or truncated by the application (as 0032 and 0033). Documents,
-- allocations, attempts and reconcile runs are append-only; an open item changes only its open
-- amount; the intake log, the cache, the counters, the series and the types are updated in place.
REVOKE DELETE, TRUNCATE ON fin.document_types, fin.number_series, fin.number_counters,
  fin.intake_requests, fin.intake_attempts, fin.documents, fin.open_items, fin.allocations,
  fin.party_balances, fin.reconcile_runs FROM app;
--> statement-breakpoint
REVOKE UPDATE ON fin.intake_attempts, fin.documents, fin.open_items, fin.allocations,
  fin.reconcile_runs FROM app;
--> statement-breakpoint
GRANT UPDATE (open_amount) ON fin.open_items TO app;
--> statement-breakpoint
CREATE TRIGGER documents_append_only BEFORE UPDATE OR DELETE ON fin.documents
  FOR EACH ROW EXECUTE FUNCTION fin.forbid_update_delete();
--> statement-breakpoint
CREATE TRIGGER documents_no_truncate BEFORE TRUNCATE ON fin.documents
  FOR EACH STATEMENT EXECUTE FUNCTION fin.forbid_update_delete();
--> statement-breakpoint
CREATE TRIGGER allocations_append_only BEFORE UPDATE OR DELETE ON fin.allocations
  FOR EACH ROW EXECUTE FUNCTION fin.forbid_update_delete();
--> statement-breakpoint
CREATE TRIGGER allocations_no_truncate BEFORE TRUNCATE ON fin.allocations
  FOR EACH STATEMENT EXECUTE FUNCTION fin.forbid_update_delete();
--> statement-breakpoint
CREATE TRIGGER intake_attempts_append_only BEFORE UPDATE OR DELETE ON fin.intake_attempts
  FOR EACH ROW EXECUTE FUNCTION fin.forbid_update_delete();
--> statement-breakpoint
CREATE TRIGGER intake_attempts_no_truncate BEFORE TRUNCATE ON fin.intake_attempts
