CREATE TRIGGER reconcile_runs_append_only BEFORE UPDATE OR DELETE ON fin.reconcile_runs
  FOR EACH ROW EXECUTE FUNCTION fin.forbid_update_delete();
--> statement-breakpoint
CREATE TRIGGER reconcile_runs_no_truncate BEFORE TRUNCATE ON fin.reconcile_runs
  FOR EACH STATEMENT EXECUTE FUNCTION fin.forbid_update_delete();
