-- An open item keeps everything but its open amount, for every role (the migrator included).
CREATE FUNCTION fin.open_item_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'fin.open_items rows are never deleted' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF (NEW.id, NEW.company_id, NEW.party_id, NEW.account_id, NEW.side, NEW.document_id,
      NEW.journal_line_id, NEW.source_system_id, NEW.group_ref, NEW.item_ref, NEW.item_date,
      NEW.due_date, NEW.amount)
     IS DISTINCT FROM
     (OLD.id, OLD.company_id, OLD.party_id, OLD.account_id, OLD.side, OLD.document_id,
      OLD.journal_line_id, OLD.source_system_id, OLD.group_ref, OLD.item_ref, OLD.item_date,
      OLD.due_date, OLD.amount) THEN
    RAISE EXCEPTION 'only the open amount of a fin.open_items row changes' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER open_items_guard BEFORE UPDATE OR DELETE ON fin.open_items
  FOR EACH ROW EXECUTE FUNCTION fin.open_item_guard();
--> statement-breakpoint
CREATE TRIGGER open_items_no_truncate BEFORE TRUNCATE ON fin.open_items
  FOR EACH STATEMENT EXECUTE FUNCTION fin.forbid_update_delete();
--> statement-breakpoint
-- The sub-ledger rule (ADR-0072 #5): every line on a party-control account carries its party and
-- opens exactly one item, checked when the transaction commits.
CREATE FUNCTION fin.control_line_has_item() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  account_control text;
BEGIN
  SELECT a.control INTO account_control
    FROM fin.accounts a WHERE a.company_id = NEW.company_id AND a.id = NEW.account_id;
  IF account_control IN ('RECEIVABLE', 'PAYABLE', 'ADVANCE_RECEIVED', 'ADVANCE_PAID') THEN
    IF NEW.party_id IS NULL THEN
      RAISE EXCEPTION 'journal line % is on a % account without a party', NEW.id, account_control
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM fin.open_items i
                    WHERE i.company_id = NEW.company_id AND i.journal_line_id = NEW.id) THEN
      RAISE EXCEPTION 'journal line % is on a % account without its open item', NEW.id, account_control
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  END IF;
  RETURN NULL;
END $$;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER journal_lines_control_item AFTER INSERT ON fin.journal_lines
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fin.control_line_has_item();
--> statement-breakpoint

-- fin_intake:data:begin
-- No copy of Finance I's vouchers or receivables (ADR-0083 #2, ADR-0090). Invoices and credit notes
-- are posted again from Bto's own tables by `pnpm finance:repost-journal` (development only); a
-- voucher has nothing to post it again from, and an entry F1's re-post made for a document would be
-- booked twice, so a database holding either stops here.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.payments) THEN
    RAISE EXCEPTION 'fin_intake: % vouchers would be lost; they are not posted again',
      (SELECT count(*) FROM public.payments);
  END IF;
  IF EXISTS (SELECT 1 FROM fin.journal_entries
              WHERE source_doc_type IN ('INVOICE', 'CREDIT_NOTE', 'PAYMENT')) THEN
    RAISE EXCEPTION 'fin_intake: % journal entries of invoices, credit notes or vouchers have no document; make the database again from one before 0033',
      (SELECT count(*) FROM fin.journal_entries WHERE source_doc_type IN ('INVOICE', 'CREDIT_NOTE', 'PAYMENT'));
  END IF;
END $$;
--> statement-breakpoint
-- The core's number series (Bto's settings page edits them): the voucher and journal formats the
-- finance settings held (else the owner's defaults, NUMBER_DEFAULTS), and the allocations' series.
INSERT INTO fin.number_series (company_id, code, pattern, digits)
  SELECT c.id, s.code, s.pattern, s.digits
    FROM fin.companies c
   CROSS JOIN LATERAL (
     SELECT 'PAYMENT' AS code,
            coalesce((SELECT payment_pattern FROM public.finance_settings WHERE id = 1), 'Т-{year}{month}{day}-') AS pattern,
            coalesce((SELECT payment_digits FROM public.finance_settings WHERE id = 1), 4) AS digits
     UNION ALL
     SELECT 'JOURNAL',
            coalesce((SELECT journal_pattern FROM public.finance_settings WHERE id = 1), 'Ж-{year}{month}{day}-'),
            coalesce((SELECT journal_digits FROM public.finance_settings WHERE id = 1), 4)
     UNION ALL
     SELECT 'ALLOCATION', 'Х-{year}{month}{day}-', 4
   ) s
   WHERE c.code = 'BO'
  ON CONFLICT DO NOTHING;
--> statement-breakpoint
-- The counters keep their place: the day's next voucher or entry number follows the last one given.
INSERT INTO fin.number_counters (company_id, scope, period, value)
  SELECT c.id, CASE n.scope_key WHEN 'PAY_NO' THEN 'PAYMENT' ELSE 'JOURNAL' END, n.period, n.last_value
    FROM public.number_sequences n CROSS JOIN fin.companies c
   WHERE c.code = 'BO' AND n.scope_key IN ('PAY_NO', 'JE_NO') AND n.last_value >= 1
  ON CONFLICT DO NOTHING;
--> statement-breakpoint
DELETE FROM public.number_sequences WHERE scope_key IN ('PAY_NO', 'JE_NO');
--> statement-breakpoint
-- Bto's document types, as the api's boot step makes them (ensureDefaultCompany).
INSERT INTO fin.document_types (company_id, code, source_system_id, class, number_mode, number_series)
  SELECT c.id, t.code, s.id, t.class, t.mode, t.series
    FROM fin.companies c
   CROSS JOIN (VALUES
     ('BTO.SALES_INVOICE', 'BTO', 'AR_INVOICE', 'SOURCE', NULL),
     ('BTO.SALES_RETURN', 'BTO', 'AR_CREDIT', 'SOURCE', NULL),
     ('FIN.CUSTOMER_RECEIPT', 'FIN', 'RECEIPT', 'CORE', 'PAYMENT'),
     ('FIN.CUSTOMER_REFUND', 'FIN', 'PAYMENT', 'CORE', 'PAYMENT'),
     ('FIN.OTHER_RECEIPT', 'FIN', 'RECEIPT', 'CORE', 'PAYMENT'),
     ('FIN.OTHER_PAYMENT', 'FIN', 'PAYMENT', 'CORE', 'PAYMENT'),
     ('FIN.JOURNAL', 'FIN', 'JOURNAL', 'CORE', 'JOURNAL'),
     ('FIN.ALLOCATION', 'FIN', 'ALLOCATION', 'CORE', 'ALLOCATION')
   ) AS t (code, system, class, mode, series)
    JOIN fin.source_systems s ON s.tenant_id = c.tenant_id AND s.code = t.system
   WHERE c.code = 'BO'
  ON CONFLICT DO NOTHING;
--> statement-breakpoint
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM fin.companies WHERE code = 'BO')
     AND ((SELECT count(*) FROM fin.document_types) <> 8
          OR (SELECT count(*) FROM fin.number_series) <> 3) THEN
    RAISE EXCEPTION 'fin_intake: the document types or the number series are incomplete';
  END IF;
END $$;
