-- The assistant's vouchers (ADR-0060 #10): the same columns over the core's voucher documents
-- (one company per installation, ADR-0088: no company filter). A voided voucher is one its
-- reversal names; the voucher's own texts are attributes.
CREATE VIEW ai.payments AS
SELECT d.id, d.number,
       CASE WHEN r.id IS NULL THEN 'POSTED' ELSE 'VOID' END AS status,
       CASE t.code WHEN 'FIN.CUSTOMER_RECEIPT' THEN 'CUSTOMER_PAYMENT'
                   WHEN 'FIN.CUSTOMER_REFUND' THEN 'CUSTOMER_REFUND'
                   WHEN 'FIN.OTHER_RECEIPT' THEN 'OTHER_IN' ELSE 'OTHER_OUT' END AS kind,
       CASE d.class WHEN 'RECEIPT' THEN 'IN' ELSE 'OUT' END AS direction,
       d.money_account_id, m.code AS money_account_code, m.name AS money_account_name,
       m.kind AS money_account_kind, br.external_id::bigint AS branch_id, b.name AS branch_name,
       c.id AS customer_id, c.code AS customer_code, c.name AS customer_name,
       g.code AS gl_account_code, g.name AS gl_account_name, d.amount,
       d.document_date AS paid_on, d.attributes ->> 'memo' AS description,
       d.attributes ->> 'reference' AS reference, d.attributes ->> 'counterparty' AS counterparty_name,
       col.full_name AS collected_by_name, cu.full_name AS created_by_name,
       d.posted_at AS created_at, r.posted_at AS voided_at, r.reverse_reason AS void_reason
  FROM fin.documents d
  JOIN fin.document_types t ON t.company_id = d.company_id AND t.id = d.document_type_id
  JOIN fin.money_accounts m ON m.company_id = d.company_id AND m.id = d.money_account_id
  LEFT JOIN fin.documents r ON r.company_id = d.company_id AND r.reverses_document_id = d.id
  LEFT JOIN fin.source_systems s ON s.code = 'BTO'
  LEFT JOIN fin.branch_refs br ON br.company_id = m.company_id AND br.branch_id = m.branch_id
                              AND br.source_system_id = s.id
  LEFT JOIN public.branches b ON b.id::text = br.external_id
  LEFT JOIN fin.party_refs pr ON pr.party_id = d.party_id AND pr.source_system_id = s.id
                             AND pr.external_id LIKE 'customer:%'
  LEFT JOIN public.customers c ON c.id::text = substr(pr.external_id, 10)
  LEFT JOIN LATERAL (
    SELECT a.code, a.name
      FROM fin.journal_entries e
      JOIN fin.journal_lines l ON l.company_id = e.company_id AND l.entry_id = e.id
      JOIN fin.accounts a ON a.company_id = l.company_id AND a.id = l.account_id
     WHERE e.company_id = d.company_id AND e.document_id = d.id
       AND l.money_account_id IS NULL AND l.party_id IS NULL
     ORDER BY l.line_no LIMIT 1) g ON true
  LEFT JOIN public.users col ON col.id::text = d.attributes ->> 'collectedBy'
  LEFT JOIN public.users cu ON 'user:' || cu.id::text = d.actor_ref
 WHERE t.code IN ('FIN.CUSTOMER_RECEIPT', 'FIN.CUSTOMER_REFUND', 'FIN.OTHER_RECEIPT', 'FIN.OTHER_PAYMENT')
   AND d.reverses_document_id IS NULL;
--> statement-breakpoint
-- The assistant's balances per customer: the core's open items on the receivable accounts (one
-- company per installation), the open invoices and their overdue amount live.
CREATE VIEW ai.customer_balances AS
SELECT c.id AS customer_id, c.code AS customer_code, c.name AS customer_name,
       c.status AS customer_status,
       coalesce(pb.open_debit - pb.open_credit, 0)::numeric(14, 2) AS balance,
       (SELECT count(*) FROM public.invoices i
         WHERE i.customer_id = c.id AND i.status = 'ISSUED' AND i.open_amount > 0)::integer AS open_invoices,
       coalesce((SELECT sum(oi.open_amount) FROM fin.open_items oi
                   JOIN fin.accounts a ON a.company_id = oi.company_id AND a.id = oi.account_id
                  WHERE oi.party_id = pr.party_id AND a.control = 'RECEIVABLE' AND oi.side = 'DEBIT'
                    AND oi.open_amount > 0
                    AND oi.due_date < (now() AT TIME ZONE 'Asia/Ulaanbaatar')::date), 0)::numeric(14, 2) AS overdue_amount,
       pb.oldest_due_date, c.credit_limit, c.credit_hold, pb.updated_at
  FROM public.customers c
  LEFT JOIN fin.source_systems s ON s.code = 'BTO'
  LEFT JOIN fin.party_refs pr ON pr.source_system_id = s.id AND pr.external_id = 'customer:' || c.id::text
  LEFT JOIN LATERAL (
    SELECT sum(b.open_debit) AS open_debit, sum(b.open_credit) AS open_credit,
           min(b.oldest_due_date) AS oldest_due_date, max(b.updated_at) AS updated_at
      FROM fin.party_balances b
      JOIN fin.accounts a ON a.company_id = b.company_id AND a.id = b.account_id
     WHERE b.party_id = pr.party_id AND a.control = 'RECEIVABLE') pb ON true;
--> statement-breakpoint
-- app's default privileges (0000_foundation) cover views too: take them back; migrate.ts grants
-- ai_reader after every run.
REVOKE ALL ON ALL TABLES IN SCHEMA ai FROM app;
